  eyebrow: string
  titleLineOne: string
  titleLineTwo: string
  titleLineThree: string
  description: string
  primaryLabel: string
  secondaryLabel: string
  menu: string[]
}

export type HeroStellarFlowProps = {
  className?: string
  brand?: string
  eyebrow?: string
  titleLineOne?: string
  titleLineTwo?: string
  titleLineThree?: string
  description?: string
  primaryLabel?: string
  secondaryLabel?: string
}

