      <ParticleField
        mode="six"
        text="HELLO"
        image=""
        speed={1}
        size={1.3}
        count={12000}
        scale={1}
        scatter={0.16}
        glow={0.8}
        depth={0.5}
        interaction={0.65}
        brilliance={1.3}
        starDensity={7}
        twinkle={0.7}
        flowSpeed={1}
        starRays={1}
        rayLength={1}
        coreGlow={1}
        rotation={0}
        color="#a9dbff"
        accentColor="#ffa66b"
        background="#03090e"
        imageColors
