        </h1>
      </div>

      <div
        className="pointer-events-none absolute right-[22vw] top-[12%] z-[4] grid size-[30px] place-items-center text-[#f4f9ff]/80 sm:right-[23.5vw] sm:top-[19%]"
        aria-hidden="true"
