  base: Float32Array
  centerY: number
  fit: number
}
const smooth = (a: number, b: number, x: number) => {
  const t = Math.min(1, Math.max(0, (x - a) / (b - a)))
  return t * t * (3 - 2 * t)
}

export function createOrbit(count: number, aspect: number, rng: () => number, galaxy = false) {
  const points = new Float32Array(count * 3),
    colors = new Float32Array(count * 3),
    activity = new Float32Array(count * 3)
  const fit = Math.min(1, aspect / 0.84),
    centerY = galaxy ? 0 : 0.11 * fit
  const state: OrbitState = {
    tracks: buildTracks(aspect, galaxy),
    lanes: new Int8Array(count),
    phases: new Float32Array(count),
    offsets: new Float32Array(count * 2),
    base: new Float32Array(count * 3),
    centerY,
    fit,
  }
  let lane = 0
  for (let i = 0; i < count; i++) {
    state.phases[i] = rng()
    if (i >= count - 4) {
      state.lanes[i] = -3
      const a = ((i - count + 4) * Math.PI * 2) / 3,
        r = i === count - 1 ? 0 : 0.003
      points.set([Math.cos(a) * r, centerY + Math.sin(a) * r, 0], i * 3)
    } else if (i % 10 === 0) {
      state.lanes[i] = -1
      points.set([(rng() - 0.5) * aspect * 1.8, (rng() - 0.5) * 1.8, (rng() - 0.5) * 0.7], i * 3)
    } else if (i % 71 === 1) {
      state.lanes[i] = -2
      state.offsets[i * 2] = rng() * Math.PI * 2
      state.offsets[i * 2 + 1] = (rng() - 0.5) * 0.035
    } else {
      state.lanes[i] = lane++ % 5
      state.offsets[i * 2] = (rng() + rng() - 1) * 0.01 * fit
      state.offsets[i * 2 + 1] = (rng() + rng() - 1) * 0.02
    }
  }
  state.base.set(points)
  advanceOrbit(state, 0, points, activity)
  return { points, colors, activity, orbit: state }
}

export function advanceOrbit(
  state: OrbitState,
  seconds: number,
  points: Float32Array,
  activity: Float32Array,
) {
  for (let i = 0; i < state.lanes.length; i++) {
    const k = i * 3,
      lane = state.lanes[i]
    activity[k] = 1
    activity[k + 1] = 1
    activity[k + 2] = 0
    if (lane === -1 || lane === -3) {
      points[k] = state.base[k]
      points[k + 1] = state.base[k + 1]
      points[k + 2] = state.base[k + 2]
      continue
    }
    if (lane === -2) {
      const p = (state.phases[i] + seconds * 0.045) % 1,
        r = 0.045 * Math.pow(1 - p, 0.7) * state.fit
      const angle = state.offsets[i * 2] - p * Math.PI * 4
      points[k] = Math.cos(angle) * r
      points[k + 1] = state.centerY + Math.sin(angle) * r
      points[k + 2] = state.offsets[i * 2 + 1] * (1 - p)
      activity[k] = smooth(0, 0.06, p) * (1 - smooth(0.94, 1, p))
      activity[k + 1] = 0.75
      activity[k + 2] = 1
      continue
    }
    const phase = (state.phases[i] + seconds * TRACK_SPEEDS[lane]) % 1
    const progress = phase + (0.34 * Math.sin(phase * Math.PI * 2)) / (Math.PI * 2)
    const s = progress * SAMPLES,
      index = Math.min(SAMPLES - 1, Math.floor(s)),
      t = s - index,
      a = index * 5,
      b = a + 5,
      table = state.tracks[lane]
    const nx = table[a + 3] + (table[b + 3] - table[a + 3]) * t,
      ny = table[a + 4] + (table[b + 4] - table[a + 4]) * t
    const offset = state.offsets[i * 2]
    points[k] = table[a] + (table[b] - table[a]) * t + nx * offset
    points[k + 1] = table[a + 1] + (table[b + 1] - table[a + 1]) * t + ny * offset
    points[k + 2] = table[a + 2] + (table[b + 2] - table[a + 2]) * t + state.offsets[i * 2 + 1]
    activity[k] = smooth(0, 0.055, progress) * (1 - smooth(0.945, 1, progress))
    activity[k + 1] = 0.3 + 0.7 * Math.pow(Math.sin(progress * Math.PI), 0.68)
    activity[k + 2] = Math.max(0, 1 - Math.hypot(points[k], points[k + 1] - state.centerY) / 0.1)
  }
}

import React, { useEffect, useRef, useState } from 'react'
import {
  defaultConfig,
  sanitizeConfig,
  makeTargets,
  vertexShader,
  fragmentShader,
  rgb,
} from './particles'
import type { ParticleConfig } from './particles'
import { advanceOrbit } from './orbits'
import type { OrbitState } from './orbits'
import { createBloom } from './bloom'

export interface ParticleFieldProps extends Partial<ParticleConfig> {
  className?: string
  replay?: number
  onStats?: (fps: number, count: number) => void
  onError?: (message: string) => void
}

/** A self-contained particle surface. Give its parent a height, or pass className. */
export default function ParticleField({
  mode = 'six',
  text = 'HELLO',
  image = '',
  speed = 1,
  size = 1.3,
  count = 12000,
  scale = 1,
  scatter = 0.16,
  glow = 0.8,
  depth = 0.5,
  interaction = 0.65,
  rotation = 0,
  brilliance = 1.3,
  starDensity = 7,
  twinkle = 0.7,
  flowSpeed = 1,
  starRays = 1,
  rayLength = 1,
  coreGlow = 1,
  color = '#a9dbff',
  accentColor = '#ffa66b',
  background = '#03090e',
  imageColors = true,
  invert = false,
  threshold = 90,
  paused = false,
  replay = 0,
  className = 'relative h-[600px] w-full',
  onStats,
  onError,
}: ParticleFieldProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null)
  const renderer = useRef<{ rebuild: () => void; replay: () => void } | null>(null)
  const config = useRef<ParticleConfig>(defaultConfig)
  const callbacks = useRef({ onStats, onError })
  const [error, setError] = useState('')
  useEffect(() => {
    config.current = sanitizeConfig({
      mode,
      text,
      image,
      speed,
      size,
      count,
      scale,
      scatter,
      glow,
      brilliance,
      starDensity,
      twinkle,
      flowSpeed,
      starRays,
      rayLength,
      coreGlow,
      depth,
      interaction,
      rotation,
      color,
      accentColor,
      background,
      imageColors,
      invert,
      threshold,
      paused,
    })
    callbacks.current = { onStats, onError }
  })

  useEffect(() => {
    const canvas = canvasRef.current!
    let disposed = false,
      frame = 0,
      abort = new AbortController()
    const report = (message: string) => {
      if (!disposed) {
        setError(message)
        callbacks.current.onError?.(message)
      }
    }
    const gl = canvas.getContext('webgl', {
      alpha: false,
      antialias: false,
      preserveDrawingBuffer: true,
      powerPreference: 'high-performance',
    })
    if (!gl) {
      report('WebGL is unavailable. Enable hardware acceleration and try again.')
      return
    }
    const shader = (type: number, source: string) => {
      const s = gl.createShader(type)!
      gl.shaderSource(s, source)
      gl.compileShader(s)
      if (!gl.getShaderParameter(s, gl.COMPILE_STATUS)) {
        const log = gl.getShaderInfoLog(s)
        gl.deleteShader(s)
        throw new Error(log || 'Shader compilation failed')
      }
      return s
    }
    const program = gl.createProgram()!
    const shaders: WebGLShader[] = []
    try {
      shaders.push(shader(gl.VERTEX_SHADER, vertexShader), shader(gl.FRAGMENT_SHADER, fragmentShader))
      shaders.forEach((s) => gl.attachShader(program, s))
      gl.linkProgram(program)
      if (!gl.getProgramParameter(program, gl.LINK_STATUS))
        throw new Error(gl.getProgramInfoLog(program) || 'Could not link particle renderer')
    } catch (e) {
      report((e as Error).message)
      shaders.forEach((s) => gl.deleteShader(s))
      gl.deleteProgram(program)
      return
    }
    let bloom: ReturnType<typeof createBloom>
    try {
      bloom = createBloom(gl)
    } catch (e) {
      report((e as Error).message)
      shaders.forEach((s) => gl.deleteShader(s))
      gl.deleteProgram(program)
      return
    }
    gl.useProgram(program)
    gl.enable(gl.BLEND)
    gl.blendFunc(gl.SRC_ALPHA, gl.ONE)
    const uniforms: Record<string, WebGLUniformLocation | null> = {}
    ;[
      'Resolution',
      'Pointer',
      'Time',
      'Morph',
      'Size',
      'Scale',
      'Scatter',
      'Depth',
      'Interaction',
      'Rotation',
      'Dpr',
      'Intro',
      'Color',
      'Accent',
      'Glow',
      'MaxPoint',
      'Brilliance',
      'StarDensity',
      'Twinkle',
      'Footprint',
      'StarRays',
      'RayLength',
      'CoreGlow',
      'Orbit',
      'DensityScale',
    ].forEach((n) => (uniforms[n] = gl.getUniformLocation(program, 'u' + n)))
    const buffers: Record<string, WebGLBuffer> = {}
    const attributes: Record<string, number> = {}
    ;['From', 'Target', 'Color', 'Seed', 'Activity', 'RayMask'].forEach((n) => {
      buffers[n] = gl.createBuffer()!
      attributes[n] = gl.getAttribLocation(program, 'a' + n)
    })
    const bindAttributes = () =>
      Object.keys(buffers).forEach((n) => {
        gl.bindBuffer(gl.ARRAY_BUFFER, buffers[n])
        gl.enableVertexAttribArray(attributes[n])
        gl.vertexAttribPointer(attributes[n], 3, gl.FLOAT, false, 0, 0)
      })
    function upload(name: string, data: Float32Array) {
      gl!.bindBuffer(gl!.ARRAY_BUFFER, buffers[name])
      gl!.bufferData(gl!.ARRAY_BUFFER, data, gl!.STATIC_DRAW)
    }
    let w = 1,
      h = 1,
      dpr = 1,
      n = 0,
      time = 0,
      morph = 1,
      intro = config.current.paused ? 1 : 0,
      last = 0,
      statsAt = 0,
      frames = 0,
      visible = true
    let from = new Float32Array(0),
      target = new Float32Array(0)
    let activity = new Float32Array(0),
      orbit: OrbitState | null = null,
      flowTime = 0
    let pointer = [10, 10],
      smoothed = [0, 0]
    const reduced = window.matchMedia('(prefers-reduced-motion: reduce)')
    const maxPoint = gl.getParameter(gl.ALIASED_POINT_SIZE_RANGE)[1]
    const rebuild = async () => {
      abort.abort()
      abort = new AbortController()
      const signal = abort.signal
      try {
        const result = await makeTargets(config.current, w / h, signal)
        if (disposed || signal.aborted) return
        const nextN = result.points.length / 3
        const nextFrom = new Float32Array(result.points.length)
        const m = morph * morph * (3 - 2 * morph)
        for (let i = 0; i < nextFrom.length; i++)
          nextFrom[i] = target.length
            ? from[i % from.length] * (1 - m) + target[i % target.length] * m
            : result.points[i]
        const hadPoints = n > 0
        from = nextFrom
        target = result.points
        activity = result.activity
        orbit = result.orbit
        flowTime = 0
        n = nextN
        morph = hadPoints ? 0 : 1
        const seeds = new Float32Array(n * 3)
        for (let i = 0; i < n * 3; i++) seeds[i] = (((Math.sin(i * 127.1 + 311.7) * 43758.5453) % 1) + 1) % 1
        // Background dust stays dim; the luminous stars belong to the shape.
        for (let i = 0; i < n; i += 10) if (i % 300 !== 0) seeds[i * 3 + 2] *= 0.83
        if (orbit) {
          for (let i = n - 4; i < n - 1; i++) seeds.set([0.4, 0.85, 0.9999], i * 3)
          seeds[n * 3 - 1] = 2
        }
        // One stable optical source per lane, never the central cluster or
        // background dust. Static image/text shapes use at most three sources.
        const rayMask = new Float32Array(n * 3)
        const candidates = new Array<number>(orbit ? 5 : 3).fill(-1)
        for (let i = 0; i < n; i++) {
          const lane = orbit ? orbit.lanes[i] : i % 3
          if (lane < 0 || i % 10 === 0) continue
          const previous = candidates[lane]
          if (previous < 0 || seeds[i * 3 + 2] > seeds[previous * 3 + 2]) candidates[lane] = i
        }
        candidates.forEach((i) => {
          if (i >= 0) rayMask[i * 3] = 1
        })
        upload('From', from)
        upload('Target', target)
        upload('Color', result.colors)
        upload('Seed', seeds)
        upload('Activity', activity)
        upload('RayMask', rayMask)
        report('')
      } catch (e) {
        if ((e as Error).name !== 'AbortError') report((e as Error).message)
      }
    }
    const resize = () => {
      const r = canvas.getBoundingClientRect(),
        oldAspect = w / h
      w = Math.max(1, r.width)
      h = Math.max(1, r.height)
      dpr = Math.min(window.devicePixelRatio || 1, 2)
      canvas.width = Math.round(w * dpr)
      canvas.height = Math.round(h * dpr)
      bloom.resize(canvas.width, canvas.height)
      if (Math.abs(oldAspect - w / h) > 0.025 || !n) void rebuild()
    }
    const observer = new ResizeObserver(resize)
    observer.observe(canvas)
    const intersection = new IntersectionObserver((entries) => {
      visible = entries[0].isIntersecting
    })
    intersection.observe(canvas)
    const move = (event: PointerEvent) => {
      const r = canvas.getBoundingClientRect()
      pointer = [(event.clientX - r.left - w / 2) / h, (event.clientY - r.top - h / 2) / h]
    }
    const leave = () => {
      pointer = [10, 10]
    }
    const lost = (event: Event) => {
      event.preventDefault()
      report('The graphics context was interrupted. Refresh the page to restore it.')
    }
    canvas.addEventListener('pointermove', move)
    canvas.addEventListener('pointerleave', leave)
    canvas.addEventListener('webglcontextlost', lost)
    renderer.current = {
      rebuild: () => void rebuild(),
      replay: () => {
        intro = 0
        time = 0
        flowTime = 0
      },
    }
    resize()
    const tick = (now: number) => {
      if (disposed) return
      frame = requestAnimationFrame(tick)
      const dt = Math.min((now - (last || now)) / 1000, 0.05)
      last = now
      if (!visible || document.hidden || gl.isContextLost()) return
      const c = config.current
      if (!c.paused && !reduced.matches) {
        time += dt * c.speed
        flowTime += dt * c.speed * c.flowSpeed
      }
      if (!c.paused) {
        morph = Math.min(1, morph + dt / 1.5)
        intro = Math.min(1, intro + dt / 2.8)
      }
      if (reduced.matches) {
        intro = 1
        morph = 1
      }
      const lerp = 1 - Math.exp(-dt * 4)
      if (!c.paused) smoothed = smoothed.map((p, i) => p + ((pointer[i] === 10 ? 0 : pointer[i]) - p) * lerp)
      if (!n) return
      if (orbit) {
        advanceOrbit(orbit, flowTime, target, activity)
        gl.bindBuffer(gl.ARRAY_BUFFER, buffers.Target)
        gl.bufferSubData(gl.ARRAY_BUFFER, 0, target)
        gl.bindBuffer(gl.ARRAY_BUFFER, buffers.Activity)
        gl.bufferSubData(gl.ARRAY_BUFFER, 0, activity)
      }
      bloom.begin()
      gl.useProgram(program)
      bindAttributes()
      gl.uniform2f(uniforms.Resolution, w, h)
      gl.uniform2f(
        uniforms.Pointer,
        pointer[0] === 10 ? 10 : smoothed[0],
        pointer[1] === 10 ? 10 : smoothed[1],
      )
      const values = {
        Time: time,
        Morph: morph,
        Size: c.size,
        Scale: c.scale,
        Scatter: c.scatter,
        Depth: c.depth,
        Interaction: reduced.matches ? 0 : c.interaction,
        Rotation: (c.rotation * Math.PI) / 180,
        Dpr: dpr,
        Intro: intro,
        Glow: c.glow,
        MaxPoint: maxPoint,
        Brilliance: c.brilliance,
        StarDensity: c.starDensity,
        Twinkle: c.twinkle,
        Footprint: orbit ? 1 : 0.72,
        StarRays: c.starRays,
        RayLength: c.rayLength,
        CoreGlow: c.coreGlow,
        Orbit: orbit ? 1 : 0,
        DensityScale: Math.min(1, (orbit ? 4500 : 6000) / n),
      }
      Object.entries(values).forEach(([key, value]) => gl.uniform1f(uniforms[key], value))
      gl.uniform3fv(uniforms.Color, rgb(c.color))
      gl.uniform3fv(uniforms.Accent, rgb(c.accentColor))
      gl.drawArrays(gl.POINTS, 0, n)
      bloom.end(rgb(c.background), c.glow)
      frames++
      if (now - statsAt > 1000) {
        callbacks.current.onStats?.(Math.round((frames * 1000) / (now - statsAt)), n)
        frames = 0
        statsAt = now
      }
    }
    frame = requestAnimationFrame(tick)
    return () => {
      disposed = true
      abort.abort()
      cancelAnimationFrame(frame)
      observer.disconnect()
      intersection.disconnect()
      canvas.removeEventListener('pointermove', move)
      canvas.removeEventListener('pointerleave', leave)
      canvas.removeEventListener('webglcontextlost', lost)
      Object.values(buffers).forEach((b) => gl.deleteBuffer(b))
      shaders.forEach((s) => gl.deleteShader(s))
      gl.deleteProgram(program)
      bloom.dispose()
      renderer.current = null
    }
  }, [])

  useEffect(() => {
    renderer.current?.rebuild()
  }, [mode, text, image, count, imageColors, invert, threshold])
  useEffect(() => {
    renderer.current?.replay()
  }, [replay])

  return (
    <div className={className}>
      <canvas
        ref={canvasRef}
        className="absolute inset-0 block h-full w-full touch-pan-y"
        role="img"
        aria-label={
          mode === 'text'
            ? `Particle text: ${text}`
            : mode === 'image'
              ? 'Custom image particle effect'
              : 'Flowing spiral particle effect'
        }
      />
      {error && (
        <div
          role="alert"
          className="absolute bottom-20 left-1/2 z-20 w-[min(90%,440px)] -translate-x-1/2 rounded-xl border border-amber-300/20 bg-[#242019]/95 px-5 py-4 text-sm leading-6 text-amber-100"
        >
          {error}
        </div>
      )}
    </div>
  )
}

import { createOrbit } from './orbits'
export type Shape = 'six' | 'galaxy' | 'text' | 'image'
export interface ParticleConfig {
  mode: Shape
  text: string
  image: string
  speed: number
  size: number
  count: number
  scale: number
  scatter: number
  glow: number
  brilliance: number
  starDensity: number
  twinkle: number
  flowSpeed: number
  starRays: number
  rayLength: number
  coreGlow: number
  depth: number
  interaction: number
  rotation: number
  color: string
  accentColor: string
  background: string
  imageColors: boolean
  invert: boolean
  threshold: number
  paused: boolean
}

export const defaultConfig: ParticleConfig = {
  mode: 'six',
  text: 'HELLO',
  image: '',
  speed: 1,
  size: 1.3,
  count: 12000,
  scale: 1,
  scatter: 0.16,
  glow: 0.8,
  depth: 0.5,
  interaction: 0.65,
  brilliance: 1.3,
  starDensity: 7,
  twinkle: 0.7,
  flowSpeed: 1,
  starRays: 1,
  rayLength: 1,
  coreGlow: 1,
  rotation: 0,
  color: '#a9dbff',
  accentColor: '#ffa66b',
  background: '#03090e',
  imageColors: true,
  invert: false,
  threshold: 90,
  paused: false,
}

export function sanitizeConfig(input: unknown): ParticleConfig {
  if (!input || typeof input !== 'object' || Array.isArray(input))
    throw new Error('Configuration must be a JSON object.')
  const data = input as Record<string, unknown>
  const c = { ...defaultConfig }
  const ranges: Record<string, [number, number]> = {
    speed: [0, 3],
    size: [0.3, 4],
    count: [1000, 30000],
    scale: [0.4, 1.6],
    scatter: [0, 1],
    glow: [0, 2],
    depth: [0, 1.5],
    interaction: [0, 2],
    rotation: [-180, 180],
    threshold: [0, 255],
    brilliance: [0.3, 2.5],
    starDensity: [0, 16],
    twinkle: [0, 1.5],
    flowSpeed: [0, 3],
    starRays: [0, 3],
    rayLength: [0.3, 2],
    coreGlow: [0, 3],
  }
  for (const [key, [min, max]] of Object.entries(ranges)) {
    if (typeof data[key] === 'number' && Number.isFinite(data[key]))
      Object.assign(c, { [key]: Math.min(max, Math.max(min, data[key])) })
  }
  c.count = Math.round(c.count)
  if (['six', 'galaxy', 'text', 'image'].includes(String(data.mode))) c.mode = data.mode as Shape
  for (const key of ['color', 'accentColor', 'background'] as const)
    if (typeof data[key] === 'string' && /^#[a-f\d]{6}$/i.test(data[key])) c[key] = data[key]
  for (const key of ['paused', 'invert', 'imageColors'] as const)
    if (typeof data[key] === 'boolean') c[key] = data[key]
  if (typeof data.text === 'string') c.text = data.text.slice(0, 80)
  if (typeof data.image === 'string' && /^(https?:\/\/|data:image\/|\/[^/])/.test(data.image))
    c.image = data.image
  return c
}

function random(seed: number) {
  return () => {
    seed |= 0
    seed = (seed + 0x6d2b79f5) | 0
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed)
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

type Sample = [number, number, number, number, number]
export async function makeTargets(c: ParticleConfig, aspect: number, signal: AbortSignal) {
  const rng = random(73124)
  if (c.mode === 'six' || c.mode === 'galaxy') return createOrbit(c.count, aspect, rng, c.mode === 'galaxy')
  const points = new Float32Array(c.count * 3)
  const colors = new Float32Array(c.count * 3)
  const samples: Sample[] = []
  if (c.mode === 'text' || c.mode === 'image') {
    const mask = document.createElement('canvas')
    mask.width = 900
    mask.height = 600
    const ctx = mask.getContext('2d', { willReadFrequently: true })!
    if (c.mode === 'text') {
      const lines = (c.text.trim() || 'HELLO').split('\n').slice(0, 4)
      const font = '700 180px Arial, "PingFang SC", sans-serif'
      ctx.font = font
      const max = Math.max(...lines.map((l) => ctx.measureText(l).width))
      const size = Math.min(210, (790 / Math.max(max, 1)) * 180, 460 / lines.length)
      ctx.font = `700 ${size}px Arial, "PingFang SC", sans-serif`
      ctx.textAlign = 'center'
      ctx.textBaseline = 'middle'
      ctx.fillStyle = '#ffffff'
      lines.forEach((line, i) => ctx.fillText(line, 450, 300 + (i - (lines.length - 1) / 2) * size * 1.12))
    } else {
      if (!c.image) throw new Error('Choose an image or enter an image URL.')
      const img = new Image()
      img.crossOrigin = 'anonymous'
      await new Promise<void>((resolve, reject) => {
        const cancel = () => {
          cleanup()
          img.src = ''
          reject(new DOMException('Aborted', 'AbortError'))
        }
        const timeout = window.setTimeout(() => {
          cleanup()
          img.src = ''
          reject(new Error('Image loading timed out. Try uploading a local image.'))
        }, 15000)
        const cleanup = () => {
          window.clearTimeout(timeout)
          signal.removeEventListener('abort', cancel)
        }
        img.onload = () => {
          cleanup()
          resolve()
        }
        img.onerror = () => {
          cleanup()
          reject(
            new Error(
              'Could not read this image. Its URL must allow cross-origin access; try uploading a local image.',
            ),
          )
        }
        signal.addEventListener('abort', cancel, { once: true })
        if (signal.aborted) {
          cancel()
          return
        }
        img.src = c.image
      })
      if (signal.aborted) throw new DOMException('Aborted', 'AbortError')
      const ratio = Math.min(820 / img.width, 520 / img.height)
      ctx.drawImage(
        img,
        (900 - img.width * ratio) / 2,
        (600 - img.height * ratio) / 2,
        img.width * ratio,
        img.height * ratio,
      )
    }
    let pixels: Uint8ClampedArray
    try {
      pixels = ctx.getImageData(0, 0, 900, 600).data
    } catch {
      throw new Error('This image blocks cross-origin sampling. Download it and upload the local file.')
    }
    const fit = Math.min(1, aspect / 1.55)
    for (let y = 0; y < 600; y += 2)
      for (let x = 0; x < 900; x += 2) {
        const i = (y * 900 + x) * 4
        const l = pixels[i] * 0.2126 + pixels[i + 1] * 0.7152 + pixels[i + 2] * 0.0722
        if (pixels[i + 3] > 50 && (c.mode === 'text' || (c.invert ? 255 - l : l) > c.threshold))
          samples.push([
            (x / 900 - 0.5) * 1.38 * fit,
            (y / 600 - 0.5) * 0.92 * fit,
            pixels[i] / 255,
            pixels[i + 1] / 255,
            pixels[i + 2] / 255,
          ])
      }
    if (!samples.length)
      throw new Error('No particles found. Lower the brightness threshold or toggle Invert brightness.')
  }
  for (let i = 0; i < c.count; i++) {
    let x = 0,
      y = 0,
      z = 0
    const field = i % 10 === 0
    if (field) {
      x = (rng() - 0.5) * aspect * 1.8
      y = (rng() - 0.5) * 1.8
      z = (rng() - 0.5) * 0.9
    } else if (samples.length) {
      const p = samples[Math.floor(rng() * samples.length)]
      x = p[0] + (rng() - 0.5) * 0.002
      y = p[1] + (rng() - 0.5) * 0.002
      z = (rng() - 0.5) * 0.05
      if (c.mode === 'image' && c.imageColors) colors.set(p.slice(2), i * 3)
    }
    points.set([x, y, z], i * 3)
  }
  return { points, colors, activity: new Float32Array(c.count * 3).fill(1), orbit: null }
}

export const vertexShader = `
precision highp float;
attribute vec3 aFrom;
attribute vec3 aTarget;
attribute vec3 aColor;
attribute vec3 aSeed;
attribute vec3 aActivity;
attribute vec3 aRayMask;
uniform vec2 uResolution;
uniform vec2 uPointer;
uniform float uTime, uMorph, uSize, uScale, uScatter, uDepth, uInteraction, uRotation, uDpr, uIntro, uMaxPoint;
uniform float uBrilliance, uStarDensity, uTwinkle, uFootprint;
uniform float uDensityScale;
uniform mediump float uStarRays, uRayLength;
uniform float uCoreGlow, uOrbit;
varying vec3 vColor;
varying float vBrightness;
varying float vStar;
varying float vExtent;
void main(){
  float m=smoothstep(0.,1.,uMorph);
  vec3 p=mix(aFrom,aTarget,m);
  float phase=aSeed.x*62.83;
  float time=uTime*(.32+aSeed.y*.35);
  vec3 motion=vec3(sin(time+phase),cos(time*.81+phase*1.3),sin(time*.6+phase*2.));
  p+=motion*(.001+uScatter*mix(.035,.006,uOrbit));
  p+=motion*sin(m*3.14159)*.13;
  p=mix(vec3(sin(phase)*aSeed.y*1.3,cos(phase)*aSeed.z, sin(phase*2.)*.7),p,smoothstep(0.,1.,uIntro));
  float c=cos(uRotation),s=sin(uRotation);
  p.xy=mat2(c,s,-s,c)*p.xy*uScale;
  vec2 delta=p.xy-uPointer;
  float dist=length(delta);
  p.xy+=delta/max(dist,.001)*exp(-dist*dist/0.011)*uInteraction*.05;
  p.xy+=uPointer*p.z*uDepth*.3*(1.-step(5.,uPointer.x));
  p.z*=uDepth;
  float perspective=1./(1.+p.z*.7);
  vec2 clip=p.xy*perspective*2.;
  clip.x/=uResolution.x/uResolution.y;
  gl_Position=vec4(clip.x,-clip.y,0.,1.);
  float bright=step(1.-uStarDensity*.01*uDensityScale,aSeed.z);
  float beacon=step(1.-uStarDensity*.0025*uDensityScale,aSeed.z)*bright;
  float wave=.5+.5*sin(uTime*(.6+aSeed.y*.8)+phase);
  float flare=pow(wave,7.)*uTwinkle;
  float shimmer=1.-uTwinkle*.3+uTwinkle*.3*sin(uTime*(.85+aSeed.y)+phase*1.7);
  float diameter=mix(2.8+aSeed.y*2.5,21.+aSeed.y*13.,bright);
  diameter=mix(diameter,42.+aSeed.y*24.,beacon);
  diameter*=mix(1.,aActivity.y,uOrbit*.6);
  float crossStar=beacon*aRayMask.x;
  vExtent=1.+crossStar*uRayLength*.8*step(.01,uStarRays);
  float screenScale=clamp(min(uResolution.x,uResolution.y)/850.,.38,1.);
  gl_PointSize=min(uMaxPoint,diameter*(1.+flare*.14*bright)*uSize*uDpr*perspective*screenScale*uFootprint*vExtent);
  if(aSeed.z>1.5){gl_PointSize=min(uMaxPoint,280.*uDpr*uSize*screenScale);vExtent=1.;}
  vStar=bright+beacon+step(1.5,aSeed.z);
  vBrightness=mix(.35+aSeed.y*.65,.65+aSeed.y*.45,bright)*shimmer;
  vBrightness*=mix(1.,uBrilliance,bright)*(1.+flare*.7*bright);
  vBrightness*=mix(1.,aActivity.x,uOrbit);
  vBrightness*=1.+uCoreGlow*aActivity.z*.18*uOrbit;
  if(aSeed.z>1.5)vBrightness=uCoreGlow*(.6+.4*smoothstep(.25,1.,uIntro))*(.94+.06*sin(uTime*.65));
  vColor=aColor;
  if(length(aColor)<.01) vColor=vec3(-1.,aSeed.x,bright);
}`

export const fragmentShader = `
precision mediump float;
uniform vec3 uColor, uAccent;
uniform float uGlow;
uniform float uStarRays, uRayLength;
varying vec3 vColor;
varying float vBrightness;
varying float vStar;
varying float vExtent;
void main(){
  vec2 q=(gl_PointCoord-.5)*2.*vExtent;
  float r=length(q);
  if(r>vExtent)discard;
  float bright=step(.5,vStar),beacon=step(1.5,vStar);
  float core=mix(exp(-r*r*18.),1.-smoothstep(.025,.12,r),bright);
  float corona=exp(-r*r*95.)*.4*bright;
  float halo=(exp(-r*r*9.)*.21+exp(-r*r*3.)*.06)*uGlow*bright;
  vec2 ray=q/(max(uRayLength,.3)*.7);
  float horizontal=exp(-abs(q.y)*95.)*(1.-smoothstep(.08,1.35,abs(ray.x)));
  float vertical=exp(-abs(q.x)*95.)*(1.-smoothstep(.08,1.35,abs(ray.y)));
  float rays=max(horizontal,vertical)*.4*uStarRays*beacon*step(1.001,vExtent);
  vec3 tint=vColor.x<0.?mix(uColor,uAccent,step(.77,vColor.y)):vColor;
  vec3 coreColor=vColor.x<0.?mix(tint,vec3(1.),bright*.83):tint;
  vec3 energy=coreColor*core+tint*(corona+halo+rays);
  if(vStar>2.5)energy=mix(tint,vec3(1.),.75)*exp(-r*r*5.)*.5*uGlow;
  // Premultiply radiance: additive blending preserves HDR-like overlapping
  // halos without clipping every individual star to a flat white square.
  gl_FragColor=vec4(energy*vBrightness,1.);
}`

export function rgb(hex: string) {
  return [1, 3, 5].map((i) => parseInt(hex.slice(i, i + 2), 16) / 255)
}
